{'code': "from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
cands = {a.objectName(): a for a in mw.findChildren(QAction) if 'プロジェクトツールバー' in a.text() or 'FileTool' in (a.objectName() or '') or 'ProjectTool' in (a.objectName() or '')}
action = cands.get('mActionToggleFileToolBar') or (next(iter(cands.values())) if cands else None)
if action is None:
    result = {'action': None, 'candidates': list(cands.keys())}
else:
    action.trigger()
    tb = mw.findChild(QToolBar, 'mFileToolBar')
    result = {'action': action.objectName(), 'checked': action.isChecked(), 'toolbar_visible': tb.isVisible() if tb else None}"}
